mutations.from:
const [vehicles, fillUps, pendingFillUps] = await Promise.all([
  repos.vehicles.listAll(),
  repos.fillUps.listAll(),
  repos.pendingFillUps.listAll(),
]);
return { vehicles, fillUps, pendingFillUps };

mutations.to:
const v = [...(await repos.vehicles.list()), ...(await repos.vehicles.listDeleted())];
const f = [...(await repos.fillUps.list()), ...(await repos.fillUps.listDeleted())];
const p = [...(await repos.pendingFillUps.list()), ...(await repos.pendingFillUps.listDeleted())];
return { vehicles: v, fillUps: f, pendingFillUps: p };

mutations.from:
await local.refresh('vehicles', vehicles.readable.map((row) => row.id));
await local.refresh('fillUps', fillUps.readable.map((row) => row.id));
await local.refresh('pendingFillUps', pending.readable.map((row) => row.id));
